/*
 * Recorded login: Form login with CSRF
 *
 * Generated by the Auth Check Recorder from a capture of https://app.example.com.
 * 2 requests, replayed in the order the browser sent them.
 * Values the server handed out -- CSRF tokens, flow ids, codes, cookies -- are
 * pulled from the response that issued them, and each request is checked
 * against the status it returned when recorded, so a login that changes
 * fails at the step that changed.
 *
 * Suggested "Session lifetime" settings:
 *   Session-check URL : https://app.example.com/dashboard
 */

params {
    param 'base', type: URL, default: 'https://app.example.com', label: 'Base URL',
          help: 'Origin the login was recorded against. Change it to replay the same flow elsewhere'
    param 'password', type: SECRET, required: true, label: 'Password'
    param 'username', type: STRING, required: true, label: 'Username'
}

def base = creds.base.replaceAll('/+$', '')

// What the browser sent on every request.
def browser = [
    'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) Chrome/142.0',
    'Accept-Language': 'en-GB,en;q=0.9'
]

// The browser kept cookies for the flow; the http helper does not, so this does.
// Keyed by host, so an identity provider and the app can both set a JSESSIONID.
def jar = [:].withDefault { [:] }

def hostOf = { String url -> (url =~ /^[A-Za-z][A-Za-z0-9+.-]*:\/\/(?:[^@\/?#]*@)?([^:\/?#]+)/).with { it.find() ? it.group(1).toLowerCase() : '' } }
def siteOf = { String host -> host.tokenize('.').takeRight(2).join('.') }

// A cookie for this URL: one its own host set, else one set elsewhere on the same site.
def cookieValue = { String url, String name ->
    String host = hostOf(url)
    if (jar[host].containsKey(name)) {
        return jar[host][name]
    }
    jar.find { h, cookies -> cookies.containsKey(name) && siteOf(h) == siteOf(host) }?.value?.get(name)
}

def cookieHeader = { String url, String... names ->
    names.findAll { cookieValue(url, it) != null }.collect { "${it}=${cookieValue(url, it)}" }.join('; ')
}

def headers = { Map extra = [:] -> (browser + extra).findAll { k, v -> v != null && v != '' } }

// Sends nothing itself: checks a response against the recording and keeps its cookies.
def step = { resp, String url, String label, int recorded ->
    int got = http.status(resp)
    if (got == 0) {
        throw new IllegalStateException("${label}: no response")
    }
    if (got.intdiv(100) != recorded.intdiv(100)) {
        throw new IllegalStateException("${label}: HTTP ${got}, but the recording got ${recorded}. " +
                "Body started: ${http.body(resp).take(300)}")
    }
    http.cookies(resp).each { name, value ->
        if (value) {
            jar[hostOf(url)][name] = value
        } else {
            jar[hostOf(url)].remove(name)
        }
    }
    resp
}

def need = { value, String what ->
    if (value == null || value == '') {
        throw new IllegalStateException("Could not find ${what}. The login flow no longer matches the recording.")
    }
    value
}

// Step 1: GET app.example.com/login  (recorded HTTP 200)
def u1 = "${base}/login"
jar[hostOf(u1)].putIfAbsent('_ga', 'GA1.2.111')  // already in the browser before recording
def r1 = step(http.get(u1, headers(['Accept': 'text/html,application/xhtml+xml', 'Cookie': cookieHeader(u1, '_ga')])), u1, 'Step 1 (GET app.example.com/login)', 200)
def csrf = need(http.extractFrom(r1, 'name="_csrf"[^>]*?value="([^"]*)"'), '_csrf (the page body of step 1)')

// Step 2: POST app.example.com/login  (recorded HTTP 302)
def u2 = "${base}/login"
jar[hostOf(u2)].putIfAbsent('_ga', 'GA1.2.111')  // already in the browser before recording
def r2 = step(http.postForm(u2, [
            '_csrf': csrf,
            'username': creds.username,
            'password': creds.password
        ], headers(['Accept': 'text/html,application/xhtml+xml', 'Origin': base, 'Referer': "${base}/login", 'Cookie': cookieHeader(u2, '_ga', 'pre_session')])), u2, 'Step 2 (POST app.example.com/login)', 302)

log.info "Logged in as ${identity} after 2 requests"

// The cookies the browser sent with the request that proved the session.
def proof = "${base}/dashboard"

return [
    cookies: [
        'pre_session': need(cookieValue(proof, 'pre_session'), 'session cookie pre_session'),
        'SESSION': need(cookieValue(proof, 'SESSION'), 'session cookie SESSION')
    ]
]
